<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class DormitoryAccessController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function board(Request $r,$building){$this->manage($r);$b=DB::table('dormitory_buildings')->find($building);abort_if(!$b,404);$rooms=DB::table('dormitory_rooms')->where('dormitory_building_id',$building)->orderBy('floor')->orderBy('number')->get()->map(function($rm){$places=DB::table('dormitory_places as p')->leftJoin('dormitory_stays as st',function($j){$j->on('st.dormitory_place_id','=','p.id')->where('st.status','=','active');})->leftJoin('students as s','s.id','=','st.student_id')->where('p.dormitory_room_id',$rm->id)->select('p.*','s.id student_id','s.last_name','s.first_name')->orderBy('p.number')->get();$rm->places=$places;return $rm;})->groupBy(fn($x)=>$x->floor??0);return view('dormitory.board',compact('b','rooms'));}
public function passes(Request $r){$this->manage($r);$rows=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->leftJoin('dormitory_passes as p',function($j){$j->on('p.student_id','=','s.id')->where('p.status','=','active');})->where('st.status','active')->select('s.id student_id','s.last_name','s.first_name','p.id pass_id','p.token','p.issued_at')->orderBy('s.last_name')->get();return view('dormitory.passes',compact('rows'));}
public function issuePass(Request $r,$student){$this->manage($r);abort_unless(DB::table('dormitory_stays')->where(['student_id'=>$student,'status'=>'active'])->exists(),422);DB::transaction(function()use($r,$student){DB::table('dormitory_passes')->where(['student_id'=>$student,'status'=>'active'])->update(['status'=>'revoked','revoked_at'=>now(),'updated_at'=>now()]);DB::table('dormitory_passes')->insert(['student_id'=>$student,'token'=>Str::random(48),'status'=>'active','issued_at'=>now(),'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return back();}
public function gate(Request $r){$this->manage($r);return view('dormitory.gate');}
public function scan(Request $r){$this->manage($r);$d=$r->validate(['token'=>'required|string|max:200','direction'=>'required|in:in,out']);$p=DB::table('dormitory_passes as p')->join('students as s','s.id','=','p.student_id')->where(['p.token'=>$d['token'],'p.status'=>'active'])->select('p.*','s.last_name','s.first_name','s.middle_name')->first();if(!$p)return response()->json(['ok'=>false,'message'=>'Пропуск не найден или отозван'],404);$stay=DB::table('dormitory_stays as st')->join('dormitory_places as pl','pl.id','=','st.dormitory_place_id')->join('dormitory_rooms as rm','rm.id','=','pl.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where(['st.student_id'=>$p->student_id,'st.status'=>'active'])->select('b.name building','rm.number room')->first();abort_if(!$stay,409,'Нет активного проживания');DB::table('dormitory_pass_events')->insert(['dormitory_pass_id'=>$p->id,'direction'=>$d['direction'],'scanned_at'=>now(),'scanned_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'student'=>trim($p->last_name.' '.$p->first_name.' '.$p->middle_name),'building'=>$stay->building,'room'=>$stay->room,'direction'=>$d['direction']]);}
public function keys(Request $r){$this->manage($r);$keys=DB::table('dormitory_keys as k')->join('dormitory_rooms as rm','rm.id','=','k.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('k.*','rm.number room_number','b.name building_name')->orderBy('b.name')->orderBy('rm.number')->get();$rooms=DB::table('dormitory_rooms as rm')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->select('rm.id','rm.number','b.name building_name')->get();$students=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('s.id','s.last_name','s.first_name')->orderBy('s.last_name')->get();$logs=DB::table('dormitory_key_logs as l')->join('dormitory_keys as k','k.id','=','l.dormitory_key_id')->join('students as s','s.id','=','l.student_id')->whereNull('l.returned_at')->select('l.*','k.key_number','s.last_name','s.first_name')->get();return view('dormitory.keys',compact('keys','rooms','students','logs'));}
public function keyStore(Request $r){$this->manage($r);$d=$r->validate(['dormitory_room_id'=>'required|exists:dormitory_rooms,id','key_number'=>'required|string|max:100']);DB::table('dormitory_keys')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
public function keyIssue(Request $r,$key){$this->manage($r);$d=$r->validate(['student_id'=>'required|exists:students,id']);DB::transaction(function()use($r,$key,$d){$k=DB::table('dormitory_keys')->where('id',$key)->lockForUpdate()->first();abort_if(!$k||$k->status!=='available',422,'Ключ уже выдан');DB::table('dormitory_key_logs')->insert(['dormitory_key_id'=>$key,'student_id'=>$d['student_id'],'issued_at'=>now(),'issued_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('dormitory_keys')->where('id',$key)->update(['status'=>'issued','updated_at'=>now()]);});return back();}
public function keyReturn(Request $r,$log){$this->manage($r);DB::transaction(function()use($r,$log){$x=DB::table('dormitory_key_logs')->where('id',$log)->lockForUpdate()->first();abort_if(!$x||$x->returned_at,404);DB::table('dormitory_key_logs')->where('id',$log)->update(['returned_at'=>now(),'returned_by'=>$r->user()->id,'updated_at'=>now()]);DB::table('dormitory_keys')->where('id',$x->dormitory_key_id)->update(['status'=>'available','updated_at'=>now()]);});return back();}
}